const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || args.instruction || '').trim();
const eventId = String(source.eventId || source.id || args.eventId || args.id || payload.eventId || payload.id || '').trim();
const query = String(source.query || args.query || payload.query || rawText).trim();
const startAt = String(source.startAt || source.start || args.startAt || args.start || payload.startAt || payload.start || new Date().toISOString()).trim();
const endAt = String(source.endAt || source.end || args.endAt || args.end || payload.endAt || payload.end || new Date(Date.now() + 60 * 60 * 1000).toISOString()).trim();
const timezone = String(source.timezone || args.timezone || payload.timezone || 'Asia/Ho_Chi_Minh').trim();
const calendarId = String(source.calendarId || args.calendarId || payload.calendarId || 'primary').trim();
const hasTarget = Boolean(eventId || query);
return [{ json: { ...source, payload, message, chatId, rawText, eventId, query, startAt, endAt, timezone, calendarId, hasTarget, response: hasTarget ? '' : 'Mia cần eventId hoặc query để đổi lịch.' } }];

const source = $('Prepare Action').item.json || {};
const rawData = $input.first().json || {};
const rows = (rawData.items || []).filter((item) => item && (item.id || item.eventId || item.summary));
if (!rows.length) {
  return [{ json: { ...source, ok: false, response: 'Mia chưa tìm thấy sự kiện phù hợp để đổi lịch.' } }];
}
const item = rows[0];
return [{ json: { ...source, ok: true, eventId: item.id || item.eventId || '', eventSummary: item.summary || source.query || '', eventLink: item.htmlLink || item.webViewLink || '' } }];

const source = $('Prepare Action').item.json || {};
const result = $json || {};
const title = source.query || result.eventSummary || source.eventId || 'sự kiện';
let text = `Đã đổi lịch sự kiện: ${title}`;
if (source.eventId || result.eventId) text += `\nEvent ID: ${source.eventId || result.eventId}`;
text += `\nThời gian mới: ${source.startAt} → ${source.endAt}`;
if (result.eventLink) text += `\nMở sự kiện: ${result.eventLink}`;
return [{ json: { chatId: source.chatId || '', text: text.trim(), eventId: source.eventId || result.eventId || '', eventLink: result.eventLink || '' } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target = source.subject || source.sender || source.query || source.messageId || source.id || '';
let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
